@namespace sv_611b5432c7eb44a998e45ae66de07861.Components.Pages.Apply
@using sv_611b5432c7eb44a998e45ae66de07861.Models

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-section-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="review-dates">@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />@r.Email &bull; @r.Phone
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(SubmitError))
        {
            <div class="validation-error">@SubmitError</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="OnBack">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceForm.ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnSubmitted { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int? ApplicationId;
    private string? SubmitError;

    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        SubmitError = null;

        try
        {
            var workHistory = new WorkHistory(
                WorkEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()
            );
            var references = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(Personal, workHistory, references, CoverLetter);

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
            await OnSubmitted.InvokeAsync(ApplicationId.Value);
        }
        catch (Exception ex)
        {
            SubmitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

