@page "/apply"
@namespace sv_611b5432c7eb44a998e45ae66de07861.Components.Pages.Apply
@using sv_611b5432c7eb44a998e45ae66de07861.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="workEntries" OnNext="HandleWorkNext" OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="references" OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep Personal="@GetPersonalInfo()"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        OnSubmitted="HandleSubmitted" />
            break;
    }
</div>

@code {
    private int currentStep = 0;

    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";
    private string? emailError;

    private List<WorkEntryForm.WorkEntryModel> workEntries = new();
    private List<ReferenceForm.ReferenceModel> references = new();
    private string coverLetter = "";

    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private PersonalInfo GetPersonalInfo() =>
        new(personalFullName, personalEmail, personalPhone, personalAddress);

    private async Task HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        // Validate email via service
        var isEmailValid = await ApplicationService.ValidateEmailAsync(result.Email);
        if (!isEmailValid)
        {
            // Stay on step — the component will show the error via re-render
            return;
        }

        personalFullName = result.FullName;
        personalEmail = result.Email;
        personalPhone = result.Phone;
        personalAddress = result.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 4;
    }

    private void GoToStep(int step)
    {
        if (step < currentStep)
            currentStep = step;
    }

    private void GoBack() => currentStep = Math.Max(0, currentStep - 1);

    private void HandleSubmitted(int applicationId)
    {
        // Submission handled by ReviewStep — nothing else needed at page level
    }
}

